=== Sensor.vue ===

const sensor = computed(() => {
    return props.sensors.find((s) => s.id === props.sensorId);
});

const emit = defineEmits<{
    (e: 'sensor-selected', sensor): void;
}>();

const imageUrl = computed(() => {
    if (sensor.value.type === 'planting-marker') {
        return 'assets/position_marker/planting-marker.svg';
    } else if (sensor.value.type === 'tree') {
        return `assets/sensors/${sensor.value.id}.svg`;
    } else {
        return `/assets/sensors/${sensor.value.type}.svg`;
    }
});
</script>

<template>
    <div @click="emit('sensor-selected', sensor)" class="relative">
<!--        <div class="absolute text-white z-40 font-extrabold text-2xl"  :style="'top:' + sensor.position.top + 'px; left: ' + sensor.position.left + 'px'">-->
<!--            {{ sensor.devEui }}-->
<!--            {{ sensor.devEui }}-->
<!--        </div>-->
        <img v-if="sensor"
            class="absolute z-30 p-4 -ml-4 -mt-4"
            :class="{ '!z-20': sensor.type === 'tree' }"
            :style="'top:' + sensor.position.top + 'px; left: ' + sensor.position.left + 'px'"
            :src="imageUrl"
        />
    </div>
</template>

